package cn.zhuatech.cpq.controller; import cn.zhuatech.cpq.common.ApiResponse; import cn.zhuatech.cpq.dto.CpqDto.*; import cn.zhuatech.cpq.service.CpqService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('PRICING_MANAGER','QUALITY','ADMIN')") public class PricingAdminController {private final CpqService service;public PricingAdminController(CpqService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<QuoteView>> orders(){return ApiResponse.ok(service.quotes());}}
